-- 0025: one credential row per account; a completed deletion job carries no
-- error; a lease column for deletion jobs; the user's time zone.
-- Generated by drizzle-kit, then hand-ordered and given the preflight and the
-- cleanup UPDATE. Every constraint and index is named (all under 63 bytes).
--
-- (a) auth.account (provider_id, account_id) becomes UNIQUE.
--     users.ts and auth-schema.ts said this rule existed; it did not, so a
--     second credential insert for the same user succeeded silently. The
--     unique index replaces the plain auth_account_provider_pair_idx on the
--     same two columns (same lookup, now enforced), so that index is dropped.
--
--     The index cannot be built over existing duplicates, and this migration
--     must never pick which credential (password hash) to delete. So it stops
--     first, with the count, and changes nothing. Run
--     scripts/auth-account-duplicates.sql on a restore of the production dump
--     before migrating; docs/migrations.md says what to do with what it finds.
DO $$
DECLARE
	dup_groups integer;
	dup_rows integer;
BEGIN
	SELECT count(*), coalesce(sum(n), 0) INTO dup_groups, dup_rows
	FROM (
		SELECT count(*) AS n FROM auth.account
		GROUP BY provider_id, account_id HAVING count(*) > 1
	) d;
	IF dup_groups > 0 THEN
		RAISE EXCEPTION '0025 refused: auth.account has % (provider_id, account_id) pair(s) held by % rows; the unique index cannot be built. Nothing was changed. Run scripts/auth-account-duplicates.sql and see docs/migrations.md (0025).', dup_groups, dup_rows
			USING ERRCODE = 'unique_violation';
	END IF;
END $$;--> statement-breakpoint
CREATE UNIQUE INDEX "auth_account_provider_account_unique" ON "auth"."account" USING btree ("provider_id","account_id");--> statement-breakpoint
DROP INDEX "auth"."auth_account_provider_pair_idx";--> statement-breakpoint
-- (b) A completed deletion job never carries last_error. deletionJobState()
--     already lets completion win; the CHECK makes the row agree. Clear any
--     stale error on a completed job first, or the constraint cannot be added.
UPDATE "privacy_deletions" SET "last_error" = NULL WHERE "completed_at" IS NOT NULL AND "last_error" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "privacy_deletions" ADD CONSTRAINT "privacy_deletions_completed_no_error_check" CHECK ("privacy_deletions"."completed_at" IS NULL OR "privacy_deletions"."last_error" IS NULL);--> statement-breakpoint
-- (c) A deletion job's claim expiry (owner decision 2026-11-09). Nullable, no
--     default: NULL = unclaimed. Written only by privacy/lifecycle.ts.
ALTER TABLE "privacy_deletions" ADD COLUMN "claimed_until" timestamp with time zone;--> statement-breakpoint
-- (d) The user's IANA time zone (owner decision 2026-11-09). NULL = unknown,
--     treated as UTC. Not a Better Auth field: written only by DocLifts server
--     code. The CHECK bounds the length; the name itself is validated in code.
ALTER TABLE "auth"."user" ADD COLUMN "time_zone" text;--> statement-breakpoint
ALTER TABLE "auth"."user" ADD CONSTRAINT "auth_user_time_zone_length_check" CHECK ("auth"."user"."time_zone" IS NULL OR char_length("auth"."user"."time_zone") BETWEEN 1 AND 64);
